CREATE TABLE public.video_walls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, columns integer NOT NULL DEFAULT 2 CHECK(columns BETWEEN 1 AND 8), rows integer NOT NULL DEFAULT 2 CHECK(rows BETWEEN 1 AND 8), width integer NOT NULL DEFAULT 3840 CHECK(width BETWEEN 320 AND 32768), height integer NOT NULL DEFAULT 2160 CHECK(height BETWEEN 180 AND 32768), gap_x integer NOT NULL DEFAULT 0 CHECK(gap_x BETWEEN 0 AND 1000), gap_y integer NOT NULL DEFAULT 0 CHECK(gap_y BETWEEN 0 AND 1000), orientation text NOT NULL DEFAULT 'landscape' CHECK(orientation IN ('landscape','portrait')), media_id uuid REFERENCES public.media(id) ON DELETE SET NULL, state text NOT NULL DEFAULT 'stopped' CHECK(state IN ('playing','paused','stopped')), epoch timestamptz NOT NULL DEFAULT now(), position_seconds double precision NOT NULL DEFAULT 0, revision bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.video_walls TO authenticated; GRANT ALL ON public.video_walls TO service_role;
ALTER TABLE public.video_walls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage walls" ON public.video_walls FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.video_wall_screens (wall_id uuid NOT NULL REFERENCES public.video_walls(id) ON DELETE CASCADE, screen_id uuid NOT NULL UNIQUE REFERENCES public.screens(id) ON DELETE CASCADE, row_index integer NOT NULL, column_index integer NOT NULL, PRIMARY KEY(wall_id,row_index,column_index));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.video_wall_screens TO authenticated; GRANT ALL ON public.video_wall_screens TO service_role;
ALTER TABLE public.video_wall_screens ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners manage wall screens" ON public.video_wall_screens FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.video_walls w WHERE w.id=wall_id AND w.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.video_walls w JOIN public.screens s ON s.user_id=w.user_id WHERE w.id=wall_id AND s.id=screen_id AND w.user_id=auth.uid()));
CREATE TABLE public.video_wall_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), wall_id uuid NOT NULL REFERENCES public.video_walls(id) ON DELETE CASCADE, action text NOT NULL, effective_at timestamptz NOT NULL, position_seconds double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_wall_events TO authenticated; GRANT ALL ON public.video_wall_events TO service_role;
ALTER TABLE public.video_wall_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read wall events" ON public.video_wall_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.video_walls w WHERE w.id=wall_id AND w.user_id=auth.uid()));
CREATE FUNCTION public.validate_wall() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE w public.video_walls; BEGIN IF TG_TABLE_NAME='video_walls' THEN IF length(trim(NEW.name)) NOT BETWEEN 1 AND 120 OR NEW.width <= (NEW.columns-1)*NEW.gap_x OR NEW.height <= (NEW.rows-1)*NEW.gap_y THEN RAISE EXCEPTION 'Invalid wall configuration'; END IF; IF NEW.media_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.media WHERE id=NEW.media_id AND user_id=NEW.user_id) THEN RAISE EXCEPTION 'Invalid media owner'; END IF; IF TG_OP='UPDATE' THEN NEW.revision=OLD.revision+1; IF NEW.media_id IS DISTINCT FROM OLD.media_id THEN NEW.state='stopped'; NEW.position_seconds=0; END IF; END IF; ELSE SELECT * INTO w FROM public.video_walls WHERE id=NEW.wall_id; IF NEW.row_index<0 OR NEW.column_index<0 OR NEW.row_index>=w.rows OR NEW.column_index>=w.columns OR NOT EXISTS(SELECT 1 FROM public.screens WHERE id=NEW.screen_id AND user_id=w.user_id) THEN RAISE EXCEPTION 'Invalid wall position or owner'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_wall BEFORE INSERT OR UPDATE ON public.video_walls FOR EACH ROW EXECUTE FUNCTION public.validate_wall();
CREATE TRIGGER validate_wall_screen BEFORE INSERT OR UPDATE ON public.video_wall_screens FOR EACH ROW EXECUTE FUNCTION public.validate_wall();
CREATE FUNCTION public.save_video_wall(p_id uuid,p_config jsonb,p_members jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE wid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_id IS NULL THEN INSERT INTO public.video_walls(user_id,name) VALUES(auth.uid(),p_config->>'name') RETURNING id INTO wid; ELSE SELECT id INTO wid FROM public.video_walls WHERE id=p_id AND user_id=auth.uid() FOR UPDATE; IF wid IS NULL THEN RAISE EXCEPTION 'Forbidden'; END IF; END IF; DELETE FROM public.video_wall_screens WHERE wall_id=wid; UPDATE public.video_walls SET name=p_config->>'name',columns=(p_config->>'columns')::int,rows=(p_config->>'rows')::int,width=(p_config->>'width')::int,height=(p_config->>'height')::int,gap_x=(p_config->>'gap_x')::int,gap_y=(p_config->>'gap_y')::int,orientation=p_config->>'orientation',media_id=NULLIF(p_config->>'media_id','')::uuid WHERE id=wid; INSERT INTO public.video_wall_screens(wall_id,screen_id,row_index,column_index) SELECT wid,(x->>'screen_id')::uuid,(x->>'row_index')::int,(x->>'column_index')::int FROM jsonb_array_elements(p_members) x; RETURN wid; END $$;
GRANT EXECUTE ON FUNCTION public.save_video_wall(uuid,jsonb,jsonb) TO authenticated;
CREATE FUNCTION public.control_video_wall(p_wall uuid,p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.video_walls; pos double precision; at_time timestamptz; BEGIN SELECT * INTO w FROM public.video_walls WHERE id=p_wall AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR p_action NOT IN ('play','pause','stop') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF p_action='play' AND (w.media_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.video_wall_screens WHERE wall_id=w.id)) THEN RAISE EXCEPTION 'Assign media and screens first'; END IF; pos=w.position_seconds+CASE WHEN w.state='playing' THEN greatest(0,extract(epoch FROM now()-w.epoch)) ELSE 0 END; at_time=CASE WHEN p_action='play' THEN now()+interval '15 seconds' ELSE now() END; UPDATE public.video_walls SET state=CASE p_action WHEN 'play' THEN 'playing' WHEN 'pause' THEN 'paused' ELSE 'stopped' END,epoch=at_time,position_seconds=CASE WHEN p_action='stop' THEN 0 ELSE pos END WHERE id=w.id; INSERT INTO public.video_wall_events(wall_id,action,effective_at,position_seconds) VALUES(w.id,p_action,at_time,CASE WHEN p_action='stop' THEN 0 ELSE pos END); END $$;
REVOKE ALL ON FUNCTION public.control_video_wall(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.control_video_wall(uuid,text) TO authenticated;
CREATE FUNCTION public.device_wall(p_device uuid,p_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; result jsonb; BEGIN sid=public.device_screen(p_device,p_hash); SELECT to_jsonb(w)||jsonb_build_object('row_index',ws.row_index,'column_index',ws.column_index,'media',CASE WHEN m.id IS NULL THEN NULL ELSE jsonb_build_object('id',m.id,'name',m.name,'type',m.type,'size',m.size,'duration',m.duration,'path',m.path) END) INTO result FROM public.video_wall_screens ws JOIN public.video_walls w ON w.id=ws.wall_id JOIN public.screens s ON s.id=ws.screen_id AND s.user_id=w.user_id LEFT JOIN public.media m ON m.id=w.media_id AND m.user_id=w.user_id WHERE ws.screen_id=sid; RETURN result-'user_id'; END $$;
REVOKE ALL ON FUNCTION public.device_wall(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.device_wall(uuid,text) TO service_role;